<template>
 <div class="corrupt-install-backdrop" @keydown.stop @keyup.stop @keydown.esc="!busy&&$emit('close')">
  <section ref="dialog" class="corrupt-installer" role="dialog" aria-modal="true" aria-labelledby="corrupt-install-title" @keydown.tab="trap">
   <header><div><small>MODULES / MUTATION PERMANENTE</small><h2 id="corrupt-install-title">{{ done?'Mutation enregistrée':pokemon?.corruption?'Modifier la corruption':'Corrompre un Pokémon' }}</h2></div><button ref="close" :disabled="busy" aria-label="Fermer" @click="$emit('close')">×</button></header>
   <div class="corrupt-install-content">
    <template v-if="done"><div class="corrupt-install-success" role="status" data-corruption-installed><pokemon-portrait v-if="pokemon" :src="sprite(pokemon)"/><h3>{{ pokemon?.name }}</h3><p>{{ done.types.map(typeName).join(' / ') }}</p><strong>{{ effect(item) }}</strong><p>Ce Pokémon est définitivement corrompu.</p></div></template>
    <template v-else>
     <label v-if="!targetPokemon" class="corrupt-target">Pokémon à modifier<select v-model="target" data-corruption-target :disabled="busy" @change="chooseTarget"><option value="">Choisir un Pokémon…</option><option v-for="p in team" :key="p.uuid" :value="p.uuid" :disabled="!!targetReason(p)">{{ p.name }} · {{ p.corruption?'Corrompu':targetReason(p)||'Sain' }}</option></select></label>
     <div v-if="pokemon" class="corrupt-target-preview"><pokemon-portrait :src="sprite(pokemon)"/><div><strong>{{ pokemon.name }}</strong><small>Niv. {{ pokemon.level }} · {{ pokemon.corruption?'Corrompu':'Sain' }}</small><span>{{ pokemon.data.type.map(typeName).join(' / ') }}</span></div></div>
     <template v-if="!presetItem"><div class="corrupt-family-filter"><button v-for="f in families" :key="f.key" :aria-pressed="family===f.key" @click="family=f.key;selectedKey='';slot=null">{{ f.label }}</button></div><label class="corrupt-module-search">Rechercher un module<input v-model="search" type="search" placeholder="Attaque, talent, type…" data-corruption-search></label><div class="corrupt-module-list"><button v-for="i in available" :key="i.key" :data-corruption-module="i.key" :aria-pressed="selectedKey===i.key" @click="selectModule(i)"><bag-item-icon :item-key="i.key" pocket="corruption"/><span><strong>{{ i.name }}</strong><small>{{ effect(i) }}</small></span><small>×{{ i.quantity }}</small></button><p v-if="!available.length">Aucun module de cette famille dans le sac.</p></div></template>
     <div v-if="item" class="corrupt-install-module"><bag-item-icon :item-key="item.key" pocket="corruption"/><div><strong>{{ item.name }}</strong><p>{{ effect(item) }}</p><small>{{ description }}</small><template v-if="item.corruptionModule.family==='move'"><p>{{ moveStats(item.corruptionModule.move) }}</p><small>{{ moveDescription(item.corruptionModule.move) }}</small></template></div></div>
     <div v-if="pokemon&&item" class="corrupt-install-preview">
      <p v-if="old" class="corrupt-old-module">Module remplacé : <strong>{{ old.name }}</strong>. Il sera détruit.</p>
      <template v-if="item.corruptionModule.family==='move'"><p v-if="autoMoveSlot>=0">{{ moveName(expectedMoves[autoMoveSlot]) }} sera remplacée par {{ moveName(item.corruptionModule.move) }}.</p><template v-else-if="expectedMoves.length===4"><p>Quelle capacité oublier ?</p><div class="corrupt-move-slots"><button v-for="(move,index) in expectedMoves" :key="index" :data-corruption-move-slot="index" :aria-pressed="slot===index" :style="typeStyle(moveType(move))" @click="slot=index"><strong>{{ moveName(move) }}</strong><small>{{ moveStats(move) }}</small><span>{{ moveDescription(move) }}</span></button></div></template><p v-else>Une place est libre : la CS prendra la place {{ expectedMoves.length+1 }}.</p><div class="corrupt-new-move" :style="typeStyle(item.corruptionModule.type)"><strong>{{ moveName(item.corruptionModule.move) }}</strong><span>{{ moveStats(item.corruptionModule.move) }}</span><p>{{ moveDescription(item.corruptionModule.move) }}</p></div></template>
      <p v-if="item.corruptionModule.family==='type'" data-corruption-type-preview>{{ typePreview }}</p>
      <p class="corrupt-permanent">La corruption est définitive. Un seul Pokémon corrompu peut être présent dans ton équipe, même K.O. Les autres peuvent rester au PC.</p>
     </div>
     <p v-if="reason" class="corrupt-install-help">{{ reason }}</p>
    </template>
   </div>
   <p v-if="error" class="corrupt-install-error" role="alert">{{ error }}</p>
   <footer><button v-if="done" class="corrupt-confirm" @click="$emit('close')">Revenir à mon Pokémon</button><template v-else><span>Un module sera consommé.</span><button class="corrupt-confirm" data-corruption-confirm :disabled="busy||!uncertain&&(!pokemon||!item||!!reason||slot===null&&item.corruptionModule.family==='move')" @click="install">{{ busy?'Mutation en cours…':uncertain?'Vérifier la mutation':old?'Confirmer le remplacement':'Confirmer la mutation' }}</button></template></footer>
  </section>
 </div>
</template>
<script>
import BagItemIcon from './BagItemIcon.vue';
import PokemonPortrait from '../PokemonPortrait.vue';
import {CORRUPTION_FAMILIES,moduleEffect,moduleAt,moduleItem,installReason} from '@/services/corruption';
import {localizeTypeName,typeBadgeStyle} from '@/services/pokemonTypes';
import {localizeMoveName} from '@/services/i18n';
import reference from '@/data/pokemonReference.fr.json';
export default{components:{BagItemIcon,PokemonPortrait},props:{items:Array,team:Array,presetItem:Object,targetPokemon:Object,initialFamily:String,source:{type:String,default:'team'},command:Function},data(){return{target:'',family:this.initialFamily||'move',search:'',selectedKey:'',slot:null,expectedMoves:[],expectedRevision:0,requestId:crypto.randomUUID(),busy:false,error:'',done:null,previous:null,uncertain:false,pending:null};},computed:{families(){return CORRUPTION_FAMILIES;},pokemon(){return this.targetPokemon||this.team?.find(p=>p.uuid===this.target);},item(){if(this.done)return moduleItem(this.done.itemKey);return this.presetItem||this.items?.find(i=>i.key===this.selectedKey);},available(){return(this.items||[]).filter(i=>i.corruptionModule?.family===this.family&&i.quantity>0&&(!this.search||(i.name+' '+moduleEffect(i)).toLocaleLowerCase('fr').includes(this.search.toLocaleLowerCase('fr')))).sort((a,b)=>a.name.localeCompare(b.name,'fr'));},old(){return this.item&&moduleAt(this.pokemon,this.item.corruptionModule.family);},reason(){return installReason(this.pokemon,this.item,this.team||[],this.source);},autoMoveSlot(){return this.pokemon?.abilities.indexOf(moduleAt(this.pokemon,'move')?.corruptionModule.move)??-1;},description(){return this.item?.corruptionModule.family==='ability'?reference.abilities[this.item.corruptionModule.ability]||'':this.item?.description;},typePreview(){const types=this.pokemon.data.type,t=this.item.corruptionModule.type,label=localizeTypeName(t);return types.includes(t)?`Le type ${label} sera retiré. Résultat : ${types.filter(x=>x!==t).map(localizeTypeName).join(' / ')||'impossible'}.`:types.length===1?`Nouveaux types : ${types.map(localizeTypeName).join(' / ')} / ${label}.`:`Un tirage remplacera ${types.map(localizeTypeName).join(' ou ')} par ${label}, à chances égales. Le movepool classique restera inchangé.`;}},watch:{targetPokemon:{handler(){this.chooseTarget();},immediate:true},presetItem(){this.chooseTarget();}},mounted(){this.previous=document.activeElement;this.$refs.close.focus();},beforeDestroy(){this.previous?.isConnected&&this.previous.focus({preventScroll:true});},methods:{typeName:localizeTypeName,typeStyle:typeBadgeStyle,effect:moduleEffect,sprite(p){return this.$assetBase+'img/pokemon/front/'+(p.spriteId||p.data?.id||p.pokemonId)+'.png';},moveName(n){return localizeMoveName(n,'fr');},moveType(n){return reference.moves[n]?.type||'Normal';},moveDescription(n){return reference.moves[n]?.description||'';},moveStats(n){const m=reference.moves[n]||{},c={physical:'Physique',special:'Spéciale',status:'Statut'}[m.category]||'—';return`${localizeTypeName(m.type)} · ${c} · ${m.power||'—'} puis. · ${m.accuracy||'—'} préc. · ${m.pp||'—'} PP`;},targetReason(p){return p.isEgg?'Œuf':p.currentHp<=0?'K.O.':!p.corruption?.permanent&&this.team.some(q=>q.corruption?.permanent)?'Un autre Pokémon est déjà corrompu':'';},chooseTarget(){this.expectedMoves=[...(this.pokemon?.abilities||[])];this.expectedRevision=this.pokemon?.corruption?.revision||0;this.slot=this.autoMoveSlot>=0?this.autoMoveSlot:this.expectedMoves.length<4?this.expectedMoves.length:null;this.error='';this.requestId=crypto.randomUUID();this.uncertain=false;this.pending=null;},selectModule(item){this.selectedKey=item.key;this.chooseTarget();},async install(){if(this.busy||!this.uncertain&&(this.reason||!this.item||!this.pokemon))return;this.busy=true;this.error='';try{const payload=this.uncertain?this.pending:{requestId:this.requestId,pokemonUuid:this.pokemon.uuid,itemKey:this.item.key,source:this.source,expectedRevision:this.expectedRevision,expectedMoves:this.expectedMoves,slot:this.slot};this.pending=payload;const result=await this.command('corruption:install',payload);if(!result.success){this.error=result.message;this.uncertain=!!result.uncertain;return;}this.done=result;this.$emit('installed',result);}catch(e){this.error=e.message;this.uncertain=true;}finally{this.busy=false;}},trap(e){const nodes=[...this.$el.querySelectorAll('button:not(:disabled),select:not(:disabled),input')].filter(n=>n.getClientRects().length),a=nodes[0],b=nodes.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();b?.focus();}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a?.focus();}}}};
</script>
<style scoped>
.corrupt-install-backdrop{position:fixed;inset:0;z-index:3550;background:#161326b8;padding:12px;display:grid;place-items:center}.corrupt-installer{width:min(740px,100%);max-height:calc(100dvh - 24px);display:flex;flex-direction:column;border:2px solid #a68ab9;background:var(--journal-paper);color:var(--journal-ink);border-radius:18px;overflow:hidden;font:13px/1.6 var(--journal-font);box-shadow:var(--journal-shadow)}header{display:flex;align-items:center;justify-content:space-between;padding:18px 22px;background:var(--journal-card);border-bottom:1px solid var(--journal-border);gap:10px}header small{font-size:9px;letter-spacing:.12em;color:var(--journal-muted)}h2{font:26px Georgia,serif;margin:5px 0;color:var(--journal-heading)}button,select,input{font:inherit;min-height:44px;border:1px solid var(--journal-border);border-radius:8px;padding:10px;background:var(--journal-card);color:var(--journal-ink);box-sizing:border-box;max-width:100%}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}header>button{font-size:24px;min-width:44px}.corrupt-install-content{overflow:auto;min-height:0;padding:18px 22px;overscroll-behavior:contain}.corrupt-target,.corrupt-module-search{display:grid;gap:7px;font-weight:600}.corrupt-target select{width:100%}.corrupt-target-preview{display:flex;align-items:center;gap:15px;padding:12px 0}.corrupt-target-preview .pokemon-portrait{width:72px;flex:none}.corrupt-target-preview strong{font-size:17px}.corrupt-target-preview small,.corrupt-target-preview span{display:block;font-size:11px;color:var(--journal-muted);margin:3px 0}.corrupt-family-filter{display:flex;gap:7px;margin:12px 0}.corrupt-family-filter button{flex:1;font-size:12px}.corrupt-family-filter [aria-pressed=true],.corrupt-module-list [aria-pressed=true]{background:var(--journal-selected);border-color:#9c73b3}.corrupt-module-search{font-size:11px;margin:12px 0}.corrupt-module-list{display:grid;grid-template-columns:1fr 1fr;gap:8px;max-height:240px;overflow:auto;padding:2px}.corrupt-module-list>button{display:flex;align-items:center;text-align:left;gap:9px;min-width:0}.corrupt-module-list .bag-object-icon{width:30px;height:30px}.corrupt-module-list span{flex:1;min-width:0}.corrupt-module-list strong{display:block;font-size:11px;overflow-wrap:anywhere}.corrupt-module-list small{font-size:10px;color:var(--journal-muted);display:block}.corrupt-install-module{display:flex;gap:16px;align-items:center;margin:14px 0;padding:14px;border:1px solid #a68ab9;border-radius:12px;background:var(--journal-card)}.corrupt-install-module>.bag-object-icon{width:48px;height:48px}.corrupt-install-module p{margin:4px 0;font-size:12px}.corrupt-install-module small{font-size:11px;color:var(--journal-muted)}.corrupt-old-module{color:var(--journal-danger);font-size:12px}.corrupt-move-slots{display:grid;grid-template-columns:1fr 1fr;gap:8px}.corrupt-move-slots button{border-left:4px solid var(--pokemon-type-color);text-align:left;padding:12px}.corrupt-move-slots [aria-pressed=true]{background:var(--journal-selected);outline:2px solid #a274b9}.corrupt-move-slots small,.corrupt-move-slots span{display:block;font-size:10px;color:var(--journal-muted);margin-top:7px}.corrupt-new-move{margin:15px 0;border-left:4px solid var(--pokemon-type-color);padding:10px 14px;background:var(--journal-card);border-radius:6px}.corrupt-new-move>strong,.corrupt-new-move>span{display:block}.corrupt-new-move>span,.corrupt-new-move p{font-size:11px}.corrupt-permanent{padding:13px;border:1px solid #ad83c3;border-radius:8px;color:var(--journal-ink);background:var(--journal-card);font-size:11px}.corrupt-install-help,.corrupt-install-error{color:var(--journal-danger);font-size:12px}.corrupt-install-error{padding:10px 22px;margin:0}footer{padding:14px 22px;background:var(--journal-card);border-top:1px solid var(--journal-border);display:flex;justify-content:space-between;align-items:center;gap:12px}footer>span{font-size:11px;color:var(--journal-muted)}.corrupt-confirm{background:#805699;color:#fff;border-color:#9d7ab0;font-weight:700}.corrupt-install-success{text-align:center;padding:15px}.corrupt-install-success .pokemon-portrait{width:120px;margin:auto}.corrupt-install-success h3{font:24px Georgia,serif;color:var(--journal-heading)}.corrupt-install-success strong{color:#956bb2}button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid #9b70b5;outline-offset:2px}
@media(max-width:560px){header{padding:14px 16px}h2{font-size:22px}.corrupt-install-content{padding:14px 16px}.corrupt-module-list{grid-template-columns:1fr;max-height:200px}.corrupt-move-slots{grid-template-columns:1fr 1fr}.corrupt-move-slots button{padding:9px;font-size:12px}.corrupt-family-filter{gap:5px}.corrupt-family-filter button{font-size:11px;padding:8px}footer{padding:12px 16px;flex-wrap:wrap}footer>button{flex:1}.corrupt-install-module{padding:12px;gap:10px}}
</style>
